Hypothesis LY : PMU.layout L.
Hypothesis HIok : heap_iface_ok L SCFG HI.
Let KL := PECKU.klayout_U L LY.

Abbreviation hi_heap := (hi_heap HI).
Abbreviation entry := (PMSP.entry CAD L).
Abbreviation enc_at := (PEC.enc_at RSEGS EE L PMSP.T3 PMSP.T4).

