(* [comment removed for export] *)
Definition galloc_spec : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LB : list (Z * Z)) (cr : credit) (n sp r : Z),
    hi_heap LB cr M (m_vmmaps model) -> PMSP.model_ok model -> K [] -> entry R M sp r 1 ->
    getr R 11%bv = Z_to_bv 64 n -> 1 <= n <= 4096 -> PMST.base_ok RSEGS CAD M ->
    PMSP.credit_le (PM.cost1 L (PEC.ESZ * n)) cr ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (cr' : credit) (B : Z),
        regs_preserved R R' -> getr R' 10%bv = Z_to_bv 64 B -> getr R' 11%bv = Z_to_bv 64 n ->
        L5C.fresh_block L LB M' B (PEC.ESZ * n) ->
        L5C.hpres L LB sp (PMSP.pm_scr 1) [] M M' ->
        PMSP.credit_keep cr cr' (PM.cost1 L (PEC.ESZ * n)) PMSP.cr0 ->
        model_but_vm model model' -> hi_heap ((B, PEC.ESZ * n) :: LB) cr' M' (m_vmmaps model') ->
        srealizes RSEGS SCFG (PMSP.cfg RSEGS R' r M' model') K) ->
    srealizes RSEGS SCFG (PMSP.cfg RSEGS R 0x38300 M model) K.

(* [comment removed for export] *)
Definition gsbdtor_spec : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LB : list (Z * Z)) (cr : credit) (q f b c al sp r : Z),
    hi_heap LB cr M (m_vmmaps model) -> PMSP.model_ok model -> K [] -> entry R M sp r 1 ->
    getr R 10%bv = Z_to_bv 64 q -> sp <= q -> q + 40 <= hl_sptop L -> q mod 8 = 0 ->
    L5.u64_at RSEGS M q f -> L5.u64_at RSEGS M (q + 8) b -> L5.u64_at RSEGS M (q + 16) b -> L5.u64_at RSEGS M (q + 24) (f + c) ->
    L5.u64_at RSEGS M (q + 32) al -> 0 <= b <= 2 ^ 47 -> 4096 <= al <= 2 ^ 47 ->
    (f = 0 \/ (In (f, c) LB /\ 1 <= c)) ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (cr' : credit),
        regs_preserved R R' ->
        L5C.hpres L (if f =? 0 then LB else lb_remove f LB) sp (PMSP.pm_scr 1) [] M M' ->
        PMSP.credit_le cr cr' ->
        model_but_vm model model' -> hi_heap (if f =? 0 then LB else lb_remove f LB) cr' M' (m_vmmaps model') ->
        srealizes RSEGS SCFG (PMSP.cfg RSEGS R' r M' model') K) ->
    srealizes RSEGS SCFG (PMSP.cfg RSEGS R 0x38298 M model) K.

(* [comment removed for export] *)
Definition gsbctor_spec : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LB : list (Z * Z)) (cr : credit) (q k al sp r : Z),
    hi_heap LB cr M (m_vmmaps model) -> PMSP.model_ok model -> K [] -> entry R M sp r 2 ->
    getr R 10%bv = Z_to_bv 64 q -> getr R 11%bv = Z_to_bv 64 (PEC.ecap (k + 1)) -> getr R 12%bv = Z_to_bv 64 (PEC.ecap k) -> getr R 13%bv = Z_to_bv 64 al ->
    0 <= k <= 11 -> sp <= q -> q + 40 <= hl_sptop L -> q mod 8 = 0 -> L5.writable RSEGS M q 40 -> 0 <= al < 2 ^ 64 ->
    PMST.base_ok RSEGS CAD M ->
    PMSP.credit_le (PM.cost1 L (PEC.ESZ * PEC.ecap (k + 1))) cr ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (cr' : credit) (B : Z),
        regs_preserved R R' ->
        L5C.fresh_block L LB M' B (PEC.ESZ * PEC.ecap (k + 1)) ->
        L5.u64_at RSEGS M' q B -> L5.u64_at RSEGS M' (q + 8) (B + PEC.ESZ * PEC.ecap k) -> L5.u64_at RSEGS M' (q + 16) (B + PEC.ESZ * PEC.ecap k) ->
        L5.u64_at RSEGS M' (q + 24) (B + PEC.ESZ * PEC.ecap (k + 1)) -> L5.u64_at RSEGS M' (q + 32) al ->
        L5C.hpres L LB sp (PMSP.pm_scr 2) [(q, 40)] M M' ->
        PMSP.credit_keep cr cr' (PM.cost1 L (PEC.ESZ * PEC.ecap (k + 1))) PMSP.cr0 ->
        model_but_vm model model' -> hi_heap ((B, PEC.ESZ * PEC.ecap (k + 1)) :: LB) cr' M' (m_vmmaps model') ->
        srealizes RSEGS SCFG (PMSP.cfg RSEGS R' r M' model') K) ->
    srealizes RSEGS SCFG (PMSP.cfg RSEGS R 0x380f4 M model) K.

