(* [comment removed for export] *)
Lemma gswap_run (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (pv q eb k ce B qe qc sp r : Z) :
  getr R (reg 10) = Z_to_bv 64 pv -> getr R (reg 11) = Z_to_bv 64 q -> getr R (reg 2) = Z_to_bv 64 sp -> getr R (reg 1) = Z_to_bv 64 r -> L5.ra_ok r ->
  sp mod 16 = 0 -> hl_sptop L - 2 ^ 23 + 32 <= sp -> 0x7fff80000000 <= hl_sptop L <= 2 ^ 47 -> sp <= pv -> sp <= q -> L5.writable RSEGS M (sp - 32) 32 ->
  pv + 24 <= hl_sptop L -> pv mod 8 = 0 -> L5.writable RSEGS M pv 24 ->
  q + 40 <= hl_sptop L -> q mod 8 = 0 -> L5.writable RSEGS M q 40 -> (pv + 24 <= q \/ q + 40 <= pv) ->
  0 <= k <= 11 ->
  L5.u64_at RSEGS M pv eb -> L5.u64_at RSEGS M (pv + 8) (eb + 24 * PEC.ecap k) -> L5.u64_at RSEGS M (pv + 16) ce ->
  L5.u64_at RSEGS M (q + 8) (B + 24 * PEC.ecap k) -> L5.u64_at RSEGS M (q + 16) qe -> L5.u64_at RSEGS M (q + 24) qc ->
  (k = 0 -> eb = 0) ->
  (0 < k -> 4096 <= eb /\ eb + 24 * PEC.ecap k <= hl_sptop L - 2 ^ 23 /\ eb mod 8 = 0 /\ L5.defined M eb (24 * PEC.ecap k)) ->
  4096 <= B -> B + 24 * PEC.ecap (k + 1) <= hl_sptop L - 2 ^ 23 -> B mod 8 = 0 -> L5.writable RSEGS M B (24 * PEC.ecap k) ->
  (B + 24 * PEC.ecap k <= eb \/ eb + 24 * PEC.ecap k <= B) ->
  0 <= ce <= 2 ^ 47 -> 0 <= qe <= 2 ^ 47 -> 0 <= qc <= 2 ^ 47 ->
  L5.img_clear M 65536 765992 ->
  exists fx' R' M', msteps RSEGS (@mkst fx R (Z_to_bv 64 0x381bc) M (seg_rom RSEGS)) (@mkst fx' R' (Z_to_bv 64 r) M' (seg_rom RSEGS))
    /\ mem_grows M M'
    /\ (forall a, 0 <= a < 2 ^ 64 -> ~ (sp - 32 <= a < sp) -> ~ (B <= a < B + 24 * PEC.ecap k) -> ~ (pv <= a < pv + 24) -> ~ (q <= a < q + 32) ->
          M' (Z_to_bv 64 a) = M (Z_to_bv 64 a))
    /\ (forall i, 0 <= i < 24 * PEC.ecap k -> M' (Z_to_bv 64 (B + i)) = M (Z_to_bv 64 (eb + i)))
    /\ L5.u64_at RSEGS M' pv B /\ L5.u64_at RSEGS M' (pv + 8) qe /\ L5.u64_at RSEGS M' (pv + 16) qc
    /\ L5.u64_at RSEGS M' q eb /\ L5.u64_at RSEGS M' (q + 8) eb /\ L5.u64_at RSEGS M' (q + 16) eb /\ L5.u64_at RSEGS M' (q + 24) ce
