Definition gslow_spec : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LR : list (Z * Z)) (cr : credit) (ov fb eb ek : Z) (estk : list eitem) (d kd pk sp r : Z),
    hi_heap (PEC.enc_own (PEC.ENC eb ek estk d) ++ LR) cr M (m_vmmaps model) -> PMSP.model_ok model -> K [] -> entry R M sp r 3 ->
    getr R 10%bv = Z_to_bv 64 (ov + 24) -> getr R 11%bv = Z_to_bv 64 pk ->
    enc_at M ov fb (PEC.ENC eb ek estk d) -> Z.of_nat (length estk) = PEC.ecap ek -> ek <= 11 ->
    sp <= ov -> ov + 56 <= hl_sptop L -> ov mod 8 = 0 ->
    sp <= pk -> pk + 8 <= hl_sptop L -> pk mod 4 = 0 -> L5.u32_at RSEGS M pk kd -> 0 <= kd <= 3 -> (pk + 4 <= ov \/ ov + 56 <= pk) ->
    PMST.base_ok RSEGS CAD M ->
    PMSP.credit_le (PM.cost1 L (PEC.ESZ * PEC.ecap (ek + 1))) cr ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (cr' : credit) (B : Z),
        regs_preserved R R' -> getr R' 10%bv = Z_to_bv 64 (B + PEC.ESZ * PEC.ecap ek + PEC.ESZ) ->
        enc_at M' ov fb (PEC.ENC B (ek + 1) (estk ++ [EI kd 0 0]) d) ->
        L5C.hpres L LR sp (PMSP.pm_scr 3) [(ov + 24, 24)] M M' ->
        PMSP.credit_keep cr cr' (PM.cost1 L (PEC.ESZ * PEC.ecap (ek + 1))) PMSP.cr0 ->
        model_but_vm model model' -> hi_heap ([(B, PEC.ESZ * PEC.ecap (ek + 1))] ++ LR) cr' M' (m_vmmaps model') ->
        srealizes RSEGS SCFG (PMSP.cfg RSEGS R' r M' model') K) ->
    srealizes RSEGS SCFG (PMSP.cfg RSEGS R 0x391b0 M model) K.

